extracted_python_code:
result = Broker.CALCULATE(
    num_faang_customers_with_com_email=COUNT(
        Customers.WHERE(
            (ENDSWITH(email, ".com")) &
            (HAS(transactions_made.WHERE(ISIN(ticker.symbol, ("AMZN", "AAPL", "GOOGL", "META", "NFLX")))) == 1)
        )
    )
)

result = Broker.CALCULATE(
    num_customers = COUNT(
        Customers.WHERE(
            (
                STARTSWITH(LOWER(name), 'j') | 
                ENDSWITH(LOWER(name), 'ez')
            ) & 
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

distinct_ticker_ids_on_or_after_date = Tickers.WHERE(
    HAS(historical_prices.WHERE(date >= "2023-04-01")) == 1
).CALCULATE(
    ticker_id=_id
)

num_transactions_recent_customers = Broker.CALCULATE(
    total_transactions_from_recent_joiners=COUNT(
        Customers.WHERE(
            DATEDIFF("days", join_date, 'now') <= 70
        ).transactions_made
    )
)

sales_by_model_with_m5_vin = Cars.WHERE(
    LIKE(vin_number, '%M5%')  # Filter cars where VIN contains 'M5' (case-insensitive partial match)
).PARTITION(
    name="car_model_group", by=(make, model)  # Group filtered cars by make and model
).CALCULATE(
    car_make=make,  # Select the make from the partition key
    car_model=model,  # Select the model from the partition key
    number_of_sales=COUNT(Cars.sale_records)  # Count all sales for cars in this make/model group
)

asp_q1_2023 = Dealership.CALCULATE(
    asp_q1_2023=AVG(
        Sales.WHERE(
            (YEAR(sale_date) == 2023) & 
            ISIN(MONTH(sale_date), (1, 2, 3))
        ).sale_price
    )
)

result = Dealership.CALCULATE(
    average_payment_lag_days=ROUND(
        AVG(
            PaymentsReceived.CALCULATE(
                days_to_pay=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_to_pay
        ),
        2
    )
)

result = Sales.WHERE(
    HAS(car.inventory_snapshots.WHERE((snapshot_date == sale_date) & (is_in_inventory == False))) == 1
).TOP_K(
    1, by=sale_price.DESC()
).CALCULATE(
    car_make=car.make,
    car_model=car.model,
    sale_price=sale_price
)

total_sales_count_last_7_days = Dealership.CALCULATE(
    TSC=COUNT(Sales.WHERE(DATEDIFF("days", sale_date, DATETIME('now')) <= 6))
)

distinct_customer_ids_with_purchases = Customers.WHERE(HAS(car_purchases) == 1).CALCULATE(
    customer_id = _id
)

cash_payment_salespersons = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(payment_method == "cash")) == 1
).CALCULATE(
    salesperson_id = _id
)

# Define the start and end dates for the 3-month period
start_period_date = DATETIME('now', '-3 months')
end_period_date = DATETIME('now')

# Find the top 3 salespersons by revenue in the last 3 months
top_sales_reps_by_revenue = Salespersons.WHERE(
    HAS(sales_made.WHERE(
        (sale_date >= start_period_date) & (sale_date <= end_period_date)
    )) == 1  # Ensure the salesperson has sales in the specified period
).CALCULATE(
    rep_first_name=first_name,
    rep_last_name=last_name,
    total_sales_num=COUNT(
        sales_made.WHERE(
            (sale_date >= start_period_date) & (sale_date <= end_period_date)
        )
    ),
    total_revenue_val=SUM(
        sales_made.WHERE(
            (sale_date >= start_period_date) & (sale_date <= end_period_date)
        ).sale_price
    )
).TOP_K(3, by=total_revenue_val.DESC())

weekend_payments_to_utility_company = Dealership.CALCULATE(
    num_weekend_payments_utility_co=COUNT(
        PaymentsMade.WHERE(
            (vendor_name == 'Utility Company') &
            (ISIN(DAYNAME(payment_date), ('Saturday', 'Sunday')))
        )
    )
)

result = Drugs.CALCULATE(
    drug_name=drug_name,
    avg_ddd=AVG(
        treatments_used_in.WHERE(
            (HASNOT(end_dt) == 0) & (DATEDIFF("days", start_dt, end_dt) > 0)
        ).CALCULATE(
            # Calculate DDD for each valid treatment
            # treatment_duration_days is implicitly DATEDIFF("days", start_dt, end_dt)
            ddd_for_treatment=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd_for_treatment
    )
)

patients_with_gmail_or_yahoo = DermTreatment.Patients.WHERE(
    ENDSWITH(email, "@gmail.com") | ENDSWITH(email, "@yahoo.com")
)
result = DermTreatment.CALCULATE(
    count_patients_gmail_yahoo=COUNT(patients_with_gmail_or_yahoo)
)

result = DermTreatment.CALCULATE(
    num_patients_diag_drug = COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (diagnosis.diag_name == 'Psoriasis vulgaris') & (drug.drug_type == 'Biologic')
                )
            ) == 1
        )
    )
)

avg_weight_drugalin_patients = DermTreatment.CALCULATE(
    average_weight = AVG(
        Drugs.WHERE(drug_name == 'Drugalin').treatments_used_in.patient.weight_kg
    )
)

caw_for_male_patients = DermTreatment.CALCULATE(
    caw_male_patients=AVG(Patients.WHERE(gender == "Male").weight_kg)
)

pic_female_patients = DermTreatment.CALCULATE(
    private_insured_female_patient_count=COUNT(
        Patients.WHERE((gender == "Female") & (ins_type == "Private"))
    )
)

result = Drugs.CALCULATE(
    drug_identifier=drug_id,
    name_of_drug=drug_name,
    num_adverse_events_in_month=SUM(
        treatments_used_in.CALCULATE(
            ae_count_for_treatment=COUNT(
                adverse_events.WHERE(
                    (YEAR(reported_dt) == YEAR(start_dt)) & (MONTH(reported_dt) == MONTH(start_dt))
                )
            )
        ).ae_count_for_treatment
    )
).TOP_K(1, by=num_adverse_events_in_month.DESC())

# Filter doctors who have prescribed biologic drugs
biologic_prescribing_doctors = Doctors.WHERE(
    HAS(prescribed_treatments.drug.WHERE(drug_type == 'biologic')) == 1
)

# Get the distinct states of these doctors
distinct_states_of_doctors = biologic_prescribing_doctors.PARTITION(
    name="states_group", by=(loc_state)
).CALCULATE(
    doctor_state=loc_state
)

result = DermTreatment.CALCULATE(
    avg_male_patient_age_private_ins=ROUND(
        AVG(
            Patients.WHERE(
                (gender == "Male") & (ins_type == "Private")
            ).CALCULATE(
                current_age=DATEDIFF("years", date_of_birth, DATETIME('now'))
            ).current_age
        )
    )
)

active_retail_merchants_with_coupons = Merchants.WHERE(
    (status == 'active') & (LOWER(category) == 'retail') & (HAS(coupons) == 1)
).CALCULATE(
    merchant_name=name,
    total_coupons_issued=COUNT(coupons)
)

user_marketing_preferences = Users.CALCULATE(
    user_id_val=uid,
    opt_in_status=setting_snapshots.WHERE(
        RANKING(by=snapshot_date.DESC(), per="Users") == 1
    ).SINGULAR().marketing_opt_in
)

result = Merchants.CALCULATE(
    mid=mid,
    name=name,
    num_coupons=COUNT(
        coupons.WHERE(
            (YEAR(coupons.created_at) == YEAR(Merchants.created_at)) &
            (MONTH(coupons.created_at) == MONTH(Merchants.created_at))
        )
    )
).TOP_K(1, by=num_coupons.DESC())

top_merchants_by_amount = Merchants.WHERE(
    # Ensure the merchant has received transactions matching the criteria
    HAS(transactions_received.WHERE(
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150) &  # Transaction within the last 150 days
        (receiver_type == 1)  # Receiver is of type 1 (Merchant)
    )) == 1
).CALCULATE(
    merchant_name=name,
    total_transactions_count=COUNT(transactions_received.WHERE(
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150) &
        (receiver_type == 1)
    )),
    total_transaction_amount=SUM(transactions_received.WHERE(
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150) &
        (receiver_type == 1)
    ).amount)
).TOP_K(
    2,  # Select top 2 merchants
    by=total_transaction_amount.DESC()  # Order by total transaction amount descending
)

avg_session_duration_by_device_type = UserSessions.PARTITION(name="sessions_by_device_type", by=(device_type)).CALCULATE(
    device_type = device_type,
    avg_session_duration_seconds = AVG(
        DATEDIFF("seconds", UserSessions.session_start_ts, UserSessions.session_end_ts)
    )
)
